<?php

declare(strict_types=1);

namespace Fleet\Domain\Model;

use Symfony\Component\Uid\Uuid;

/**
 * Identity of an agent (UUID v7, generated by the caller so the audit always knows its target).
 */
final readonly class AgentId
{
    private function __construct(public Uuid $value)
    {
    }

    public static function fromString(string $id): self
    {
        return new self(Uuid::fromString($id));
    }

    public static function of(Uuid $id): self
    {
        return new self($id);
    }

    public function toString(): string
    {
        return $this->value->toRfc4122();
    }
}
